    return len(s1) == len(s2) and s2 in (s1 + s1)

def preprocess(s):
    n = len(s)
    lps = [0] * n
    j = 0
    for i in range(1, n):
        while (j > 0 and s[i] != s[j]):
            j = lps[j - 1]
        if s[i] == s[j]:
            j += 1
            lps[i] = j
    return lps

